import esbuild from "esbuild";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const appRoot = path.resolve(__dirname, "..");
const repoRoot = path.resolve(appRoot, "../..");
const entry = path.join(appRoot, "src/terminal/webview/terminal-emulator-webview-entry.ts");
const output = path.join(appRoot, "src/terminal/webview/terminal-emulator-webview-html.ts");

async function resolveTsPath(basePath) {
  const candidates = [
    basePath,
    `${basePath}.ts`,
    `${basePath}.tsx`,
    `${basePath}.js`,
    `${basePath}.jsx`,
    path.join(basePath, "index.ts"),
    path.join(basePath, "index.tsx"),
    path.join(basePath, "index.js"),
    path.join(basePath, "index.jsx"),
  ];
  for (const candidate of candidates) {
    try {
      const stat = await fs.stat(candidate);
      if (stat.isFile()) return candidate;
    } catch {
      // try next candidate
    }
  }
  return basePath;
}

const aliasPlugin = {
  name: "chisacode-alias",
  setup(build) {
    build.onResolve({ filter: /^@\// }, async (args) => ({
      path: await resolveTsPath(path.join(appRoot, "src", args.path.slice(2))),
    }));
    build.onResolve({ filter: /^@server\// }, async (args) => ({
      path: await resolveTsPath(
        path.join(repoRoot, "packages/server/src", args.path.slice("@server/".length)),
      ),
    }));
  },
};

const browserNodeBuiltinsPlugin = {
  name: "chisacode-browser-node-builtins",
  setup(build) {
    // The ligatures addon bundles lru-cache's Node diagnostics import into its browser build.
    build.onResolve({ filter: /^node:diagnostics_channel$/ }, () => ({
      path: "node:diagnostics_channel",
      namespace: "chisacode-browser-shim",
    }));
    build.onLoad({ filter: /.*/, namespace: "chisacode-browser-shim" }, () => ({
      contents: `
const channelInstance = {
  hasSubscribers: false,
  publish() {},
  subscribe() {},
  unsubscribe() {},
  bindStore() {},
  unbindStore() {},
  runStores(_context, fn, thisArg, ...args) {
    return Reflect.apply(fn, thisArg, args);
  },
};

const tracingChannelInstance = {
  hasSubscribers: false,
  start: channelInstance,
  end: channelInstance,
  asyncStart: channelInstance,
  asyncEnd: channelInstance,
  error: channelInstance,
  traceSync(fn, _context, thisArg, ...args) {
    return Reflect.apply(fn, thisArg, args);
  },
  tracePromise(fn, _context, thisArg, ...args) {
    return Promise.resolve(Reflect.apply(fn, thisArg, args));
  },
  traceCallback(fn, _position, _context, thisArg, ...args) {
    return Reflect.apply(fn, thisArg, args);
  },
};

export function channel() {
  return channelInstance;
}

export function tracingChannel() {
  return tracingChannelInstance;
}
`,
      loader: "js",
    }));
  },
};

const result = await esbuild.build({
  entryPoints: [entry],
  bundle: true,
  write: false,
  format: "iife",
  platform: "browser",
  target: ["ios15", "chrome100"],
  loader: {
    ".css": "text",
  },
  plugins: [browserNodeBuiltinsPlugin, aliasPlugin],
  logLevel: "info",
});

const js = result.outputFiles[0]?.text;
if (!js) {
  throw new Error("terminal webview bundle produced no JavaScript");
}

const html = `<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta
      name="viewport"
      content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover"
    />
  </head>
  <body>
    <script>${js}</script>
  </body>
</html>`;

const contents = `// Generated by packages/app/scripts/build-terminal-webview-html.mjs.
// Do not edit by hand.

export const terminalEmulatorWebViewHtml = ${JSON.stringify(html)};
`;

await fs.writeFile(output, contents);
console.log(`Wrote ${path.relative(repoRoot, output)} (${html.length} bytes)`);
